  "implementation": "def solve(case):
    nodes = case.get('nodes')
    core_distance = case.get('core_distance')
    distances = case.get('distances')
    if nodes is None or core_distance is None or distances is None:
        raise ValueError('Missing required fields')
    if not isinstance(nodes, list) or not all(isinstance(n, str) for n in nodes):
        raise ValueError('nodes must be list of strings')
    if not isinstance(core_distance, dict):
        raise ValueError('core_distance must be dict')
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f'core_distance missing node {node}')
    if not isinstance(distances, list) or not all(isinstance(e, list) and len(e)==3 and isinstance(e[0], str) and isinstance(e[1], str) and isinstance(e[2], (int, float)) for e in distances):
        raise ValueError('distances must be list of [node,node,number]')
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        w = max(core_distance[u], core_distance[v], d)
        edges.append((w, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) < len(nodes) - 1:
        raise ValueError('Disconnected graph')
    return {'mst_edges': mst_edges, 'total_weight': total}
